def _mini(j):
    nama = [m[0] for m in j['mini']]
    brief = j['mini'][0]
    code = (f"BRIEF PROYEK MINI: {brief[0]}\n\nTujuan latihan : {brief[1]}\nFitur wajib    : {brief[2]}\nTantangan      : {brief[3]}\n\n"
            "Definisi selesai\n[ ] Semua fitur wajib berjalan, termasuk input salah dan data kosong\n[ ] Repo publik dengan README (screenshot, cara menjalankan)\n"
            "[ ] Minimal satu test atau bukti pengujian\n[ ] Bisa didemokan dalam 2 menit\n\nWaktu ideal: 3-7 hari per proyek mini")
    return C(f"Proyek mini: {j['k']}",
             [f"Tiga proyek mini ini melatih keterampilan inti jalur <b>{j['k']}</b> satu per satu (materinya ada di jalur {j['jalur']}). Masing-masing cukup dikerjakan dalam 3–7 hari.",
              'Kerjakan berurutan. Setiap proyek mini harus "selesai" menurut definisi di bawah: berfungsi termasuk kasus gagal, ada README, dan bisa didemokan. Proyek mini yang tuntas lebih berharga daripada proyek besar yang setengah jadi.',
              'Setelah ketiganya selesai, keterampilannya akan dipakai bersama di proyek besar jalur ini.'],
             code, None, 'text',
             tb=[{'c': f"Proyek mini {j['k']}", 'h': ['Proyek', 'Yang dilatih', 'Fitur wajib', 'Tantangan tambahan'], 'r': [list(m) for m in j['mini']]}],
             pts=[f"{n}." for n in nama],
             qs=[q('Kapan sebuah proyek mini dianggap selesai?', ['Fitur wajib berjalan termasuk kasus gagal, ada README, dan bisa didemokan', 'Saat kodenya sudah ditulis', 'Saat sudah ada 1.000 baris kode'], 0, 'Selesai = bisa dipakai dan ditunjukkan.')])


def _cap(j):
    nama, masalah, fitur, stack, minggu, standar = j['cap']
    code = (f"PROYEK BESAR: {nama}\n\nMasalah\n  {masalah}\n\nFitur wajib\n" + ''.join(f"  {i+1}. {f}\n" for i, f in enumerate(fitur)) +
            f"\nStack yang disarankan\n  {stack}\n\nRencana 4 minggu\n" + ''.join(f"  {m}\n" for m in minggu) +
            f"\nStandar industri yang dinilai\n  {standar}\n\nKeluaran\n  [ ] Repo dengan README lengkap, keputusan teknis, dan screenshot\n  [ ] Demo online atau video 2 menit\n  [ ] Test/bukti pengujian dan CI hijau (untuk proyek kode)\n  [ ] Ringkasan 1 paragraf untuk CV dan LinkedIn")
    return C(f"Proyek besar: {nama}",
             [f"Proyek besar (capstone) jalur <b>{j['k']}</b>. Masalahnya nyata: {masalah} Kerjakan dalam sekitar <b>4 minggu</b> dengan rencana mingguan di bawah.",
              'Perlakukan seperti pekerjaan di tim: tulis kebutuhan dulu, pecah menjadi issue di GitHub Projects, kerjakan per branch dan pull request, dan catat keputusan teknis di README. Nilai dirimu dengan rubrik di modul pertama jalur ini.',
              f"Yang membedakan proyek ini dari tutorial: {standar[0].lower() + standar[1:]}. Itulah yang akan kamu ceritakan saat wawancara."],
             code, None, 'text',
             tb=[{'c': 'Fitur wajib dan bukti yang ditunjukkan', 'h': ['No', 'Fitur', 'Bukti di portofolio'], 'r': [
                 [str(i + 1), f, 'Demo/screenshot + test atau penjelasan di README'] for i, f in enumerate(fitur)]}],
             pts=[f"Masalah: {masalah}", f"Stack: {stack}.", 'Rencana 4 minggu; dinilai dengan rubrik standar industri.'],
             qs=[q('Cara kerja yang disarankan untuk proyek besar?', ['Pecah jadi issue, kerjakan per branch dan PR, catat keputusan teknis', 'Kerjakan semua sekaligus lalu satu commit', 'Salin proyek orang lain'], 0, 'Meniru cara kerja tim sungguhan.')])


